import { CHAIN, CONTRACTS } from './chain-config.js';

// RNG indices and result cursors belong to one GAME deployment.
const DEPLOYMENT = `${String(CONTRACTS.GAME || '').toLowerCase()}:${CHAIN.deployBlock}`;

export function pendingBoxesKey(chainId, address) {
  return `pending-boxes:${chainId}:${String(address || '').toLowerCase()}:${DEPLOYMENT}`;
}

export function revealedBoxesKey(chainId, address) {
  return `revealed-lootboxes:${chainId}:${String(address || '').toLowerCase()}:${DEPLOYMENT}`;
}

export function lootboxResultCursorKey(chainId, address) {
  return `lootbox-result-cursor:${chainId}:${String(address || '').toLowerCase()}:${DEPLOYMENT}`;
}
